./novamind-operation python-c "
import novamind_api as nm, collections
r = nm.query('''SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.closed, t.offer_json FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.day>168 AND t.sender<>'agent' AND NOT (t.sender='system' AND t.turn_number>0) ORDER BY t.thread_id, t.turn_number''')
acc = {}; cnt=[]; churn=[]; new={}
for x in r['rows']:
    g=x['group_id']; tt=x['thread_type']; oj=x['offer_json']
    if x['sender']=='customer' and tt=='new_lead':
        if x['closed']: acc.setdefault(g,[]).append(oj)
        else: cnt.append((x['customer_id'],g,x['seat_count'],'t%d'%x['turn_number'],oj))
    elif x['sender']=='customer' and tt=='churn_prevention':
        if x['closed']: acc.setdefault(g+'_churn',[]).append(oj)
        elif x['turn_number']==1: churn.append((x['customer_id'],g,x['seat_count']))
        else: cnt.append((x['customer_id'],g,x['seat_count'],'churn_t%d'%x['turn_number'],oj))
    elif x['sender']=='system' and x['turn_number']==0 and tt=='new_lead':
        new.setdefault(g,[]).append((x['customer_id'],x['seat_count']))
for g,l in acc.items():
    c=collections.Counter(l); print('ACCEPTED',g,len(l),dict(c))
print('COUNTERS/OPEN:'); [print('  ',c) for c in cnt]
print('NEW CHURN THREADS:', len(churn)); print('  ', [c[0] for c in churn])
for g,l in new.items(): print('NEW',g,len(l),'seats',sum(s for _,s in l)); print('   ids', [i for i,_ in l])
" 2>&1 | grep -v request_id

