r = nm.query('''SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.closed, t.offer_json FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.day>%d AND t.sender<>'agent' AND NOT (t.sender='system' AND t.turn_number>0) ORDER BY t.thread_id, t.turn_number''' % D)
acc = {}; cnt=[]; churn=[]; new={}
for x in r['rows']:
    g=x['group_id']; tt=x['thread_type']; oj=x['offer_json']
    if x['sender']=='customer' and tt=='new_lead':
        if x['closed']: acc.setdefault(g,[]).append(oj)
        else: cnt.append((x['customer_id'],g,x['seat_count'],'t%d'%x['turn_number'],oj))
    elif x['sender']=='customer' and tt=='churn_prevention':
        if x['closed']: acc.setdefault(g+'_churn',[]).append(oj)
        elif x['turn_number']==1: churn.append((x['customer_id'],g,x['seat_count']))
        else: cnt.append((x['customer_id'],g,x['seat_count'],'churn_t%d'%x['turn_number'],oj))
    elif x['sender']=='system' and x['turn_number']==0 and tt=='new_lead':
        new.setdefault(g,[]).append((x['customer_id'],x['seat_count']))
for g,l in acc.items():
    c=collections.Counter(l); print('ACCEPTED',g,len(l),dict(c))
print('COUNTERS/OPEN:'); [print('  ',c) for c in cnt]
print('NEW CHURN THREADS:', len(churn)); print('  ', [(c[0],c[1]) for c in churn])
for g,l in new.items(): print('NEW',g,len(l),'seats',sum(s for _,s in l)); print('   ids', [i for i,_ in l])
def q(sql, label):
    r = nm.query(sql); print('==', label)
    for x in r['rows']: print('  ', x)
q('''SELECT c.group_id, COUNT(*) n, SUM(s.seat_count) seats, ROUND(AVG(s.effective_price),2) px FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='subscribed' GROUP BY 1 ORDER BY 1''', 'enterprise subs')
q('''SELECT c.group_id, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='cancelled' AND s.end_day>%d GROUP BY 1''' % D, 'enterprise cancels')
q('''SELECT s.end_day, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>%d AND c.customer_type='small' GROUP BY 1''' % D, 'indiv cancels by day')
q('''SELECT day, COUNT(*) n FROM ledger WHERE category='subscription_payment' AND day>%d GROUP BY day''' % D, 'payments by day')
q('''SELECT c.group_id, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs, SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.created_day>%d AND c.customer_type='small' GROUP BY 1 ORDER BY 1''' % D, 'conversion by group')
q('''SELECT category, ROUND(SUM(amount)) total FROM ledger WHERE day>%d GROUP BY 1 ORDER BY 2''' % D, 'ledger')
q('''SELECT day, ROUND(SUM(amount)) net, ROUND(SUM(CASE WHEN category='subscription_payment' THEN amount END)) rev FROM ledger WHERE day>%d GROUP BY day''' % D, 'daily')
q('''SELECT day, substr(content,1,90) c FROM social_media_posts WHERE day>%d AND (content LIKE '%%boost%%' OR content LIKE '%%overhaul%%' OR content LIKE '%%release%%') ORDER BY post_id DESC LIMIT 6''' % D, 'competitor posts')
q('''SELECT CASE WHEN days_open=0 THEN '0' WHEN days_open<=3 THEN '1-3' ELSE '4+' END b, COUNT(*) n FROM issues WHERE status='open' GROUP BY 1''', 'issue aging')
q('''SELECT MAX(total_usage_units) peak FROM service_day WHERE day>%d''' % D, 'usage peak')
q('''SELECT channel_id, group_id, SUM(leads_generated) leads, SUM(spend) spend, ROUND(1000.0*SUM(leads_generated)/SUM(spend),1) lp1k FROM ad_channel_leads WHERE day>%d GROUP BY 1,2 ORDER BY 2,5 DESC''' % D, 'channels')
q('''SELECT project_id, tier, status, expected_completion_day, ROUND(quality_boost_applied,3) q FROM research_projects WHERE status='completed' AND expected_completion_day>%d''' % D, 'rnd completed this week')

