import novamind_api as nm, json, sys, collections
D = int(sys.argv[1]); DRY = len(sys.argv) > 2 and sys.argv[2] == 'dry'
prices = json.load(open('prices.json'))
hi = {'E2','E3','D_E03','D_E07','D_E08','D_E04','D_E01','D_E05'}
def q(sql, label=None, show=True):
    r = nm.query(sql)['rows']
    if label and show:
        print('==', label)
        for x in r: print('  ', x)
    return r
# ---------- review ----------
acc = q('''SELECT c.group_id, t.thread_type, t.offer_json, t.turn_number FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.day>%d AND t.sender='customer' AND t.closed AND t.close_reason='accepted' ''' % D, show=False)
byg = collections.defaultdict(collections.Counter)
for x in acc:
    key = x['group_id'] + ('_churn' if x['thread_type']=='churn_prevention' else '')
    try: p = json.loads(x['offer_json']).get('price')
    except Exception: p = None
    byg[key][p] += 1
for k in sorted(byg): print('ACCEPTED', k, sum(byg[k].values()), dict(sorted(byg[k].items(), key=lambda kv: -kv[0] if kv[0] else 0)))
q('''SELECT c.group_id, COUNT(*) n, SUM(s.seat_count) seats, ROUND(AVG(s.effective_price),2) px FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='subscribed' GROUP BY 1''', 'enterprise subs')
q('''SELECT c.group_id, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='cancelled' AND s.end_day>%d GROUP BY 1''' % D, 'enterprise cancels')
q('''SELECT s.end_day, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>%d AND c.customer_type='small' GROUP BY 1''' % D, 'indiv cancels by day')
q('''SELECT c.group_id, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>%d AND c.customer_type='small' GROUP BY 1,2 ORDER BY n DESC LIMIT 6''' % D, 'indiv cancels top group/plan')
q('''SELECT c.group_id, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='small' AND s.start_day>%d GROUP BY 1,2 ORDER BY n DESC LIMIT 6''' % D, 'new indiv subs top group/plan')
q('''SELECT category, ROUND(SUM(amount)) total FROM ledger WHERE day>%d GROUP BY 1 ORDER BY 2''' % D, 'ledger')
q('''SELECT day, ROUND(SUM(amount)) net, ROUND(SUM(CASE WHEN category='subscription_payment' THEN amount END)) rev, ROUND(SUM(CASE WHEN category='subscription_payment' AND amount>=1000 THEN amount END)) ent FROM ledger WHERE day>%d GROUP BY day''' % D, 'daily')
q('''SELECT day, substr(content,1,80) c FROM social_media_posts WHERE day>%d AND (content LIKE '%%boost%%' OR content LIKE '%%overhaul%%' OR content LIKE '%%release%%') ORDER BY post_id DESC LIMIT 6''' % D, 'competitor posts')
q('''SELECT MAX(total_usage_units) peak FROM service_day WHERE day>%d''' % D, 'usage peak')
q('''SELECT channel_id, group_id, SUM(leads_generated) leads, SUM(spend) spend, ROUND(1000.0*SUM(leads_generated)/SUM(spend),1) lp1k FROM ad_channel_leads WHERE day>%d GROUP BY 1,2 ORDER BY 2,5 DESC''' % D, 'channels')
done = q('''SELECT project_id, tier, status, expected_completion_day, ROUND(quality_boost_applied,3) q FROM research_projects WHERE status='completed' AND expected_completion_day>%d''' % D, 'rnd completed this week')
q('''SELECT tier, status, expected_completion_day FROM research_projects WHERE status<>'completed' ORDER BY expected_completion_day''', 'rnd in progress')
# ---------- pending threads ----------
last = q('''SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.seat_count, t.offer_json FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.closed=0 AND t.turn_number = (SELECT MAX(turn_number) FROM enterprise_turns u WHERE u.thread_id=t.thread_id) AND NOT EXISTS (SELECT 1 FROM enterprise_turns v WHERE v.thread_id=t.thread_id AND v.closed=1) AND t.sender<>'agent' ''', show=False)
agent1 = {}
tids = [x['thread_id'] for x in last if x['thread_type']=='new_lead' and x['turn_number']>=2]
if tids:
    for x in q('''SELECT thread_id, offer_json FROM enterprise_turns WHERE sender='agent' AND turn_number=1 AND thread_id IN (%s)''' % ','.join(map(str,tids)), show=False):
        try: agent1[x['thread_id']] = max(o['price_per_seat'] for o in json.loads(x['offer_json']))
        except Exception: pass
cids = list({x['customer_id'] for x in last})
price = {}
for i in range(0, len(cids), 400):
    for x in q("SELECT customer_id, effective_price FROM subscriptions WHERE status='subscribed' AND customer_id IN (%s)" % ",".join(map(str,cids[i:i+400])), show=False):
        price[x['customer_id']] = x['effective_price']
deals = []; log = collections.Counter(); newl = collections.defaultdict(list); skipped = []
for x in last:
    cid, g, tt, tn, sender = x['customer_id'], x['group_id'], x['thread_type'], x['turn_number'], x['sender']
    try: their = json.loads(x['offer_json'] or '{}').get('price')
    except Exception: their = None
    if tt == 'churn_prevention':
        p = price.get(cid)
        if p is None: skipped.append((cid, g, tt, tn)); continue
        if tn == 1:
            val = round(max(p*(0.75 if g in hi else 0.85), 2.0), 2); log['churn_t1'] += 1
        elif tn == 3:
            val = their if (their is not None and their >= 0.5*p) else round(max(0.55*p, their or 0), 2); log['churn_t3'] += 1
        else:
            val = their if their is not None else round(0.5*p, 2); log['churn_t5+'] += 1
        deals.append([cid, [["C", val]]])
    else:
        if sender == 'system' and tn == 0:
            C = prices.get(g)
            if C is None: skipped.append((cid, g, tt, tn)); continue
            off = [["C", C], ["B", round(C*0.75)]] + ([["A", round(C*0.5)]] if g == 'E1' else [])
            deals.append([cid, off]); newl[g].append(x['seat_count'])
        elif tn == 2 and their is not None:
            mine = agent1.get(x['thread_id'], prices.get(g, 0))
            val = their if their >= 0.5*mine else round((their + mine)/2, 2)
            deals.append([cid, [["C", val]]]); log['lead_t2'] += 1
        elif their is not None:
            deals.append([cid, [["C", their]]]); log['lead_t4+'] += 1
        else: skipped.append((cid, g, tt, tn))
print('PENDING', len(last), 'deals', len(deals), dict(log), 'skipped', skipped[:10])
print('NEW LEADS', {g: (len(v), sum(v)) for g, v in newl.items()})
if not DRY and deals:
    out = []
    for i in range(0, len(deals), 300):
        r = nm.enterprise.send_enterprise_deal(deals[i:i+300]); out += r.get('results', [])
    print('SENT', len(out), 'ok', sum(1 for x in out if x.get('success')), 'fail', [x for x in out if not x.get('success')][:5])
for x in done:
    if not DRY and x['tier'] <= 8:
        try: print('RND restart', x['tier'], json.dumps(nm.research.start_research_project(x['tier']))[:160])
        except Exception as e: print('RND err', x['tier'], e)
EOF
